@startuml

class InsuranceCompany {
  + companyName : string
  + registrationNumber : string
}

class Policy {
  + policyType : string
  + coverageAmount : double
  + startDate : date
  + endDate : date
}

class Customer {
  + customerId : int
  + name : string
  + email : string
}

class Contract {
  + contractId : int
  + signingDate : date
  + status : string
}

InsuranceCompany "1" -- "1..*" Policy : issues
InsuranceCompany "1" -- "1..*" Customer : manages
Customer "1" -- "0..*" Contract : signs
Contract "1" -- "1" Policy : covers

@enduml

